import { GEO } from './nyc-geodata.js';
import {
  MUSEUM_ORIGIN,
  MUSEUM_HALL,
  MUSEUM_BOUNDS,
  MUSEUM_TELEPORTS,
  MUSEUM_EXHIBITS,
  COLONNADE_ZS,
  getMuseumZoneAt
} from './museum-config.js';

// New York City spatial configuration & street database at true 1:1 scale, derived from the real geography in
// js/nyc-geodata.js (generated by tools/build-geodata.mjs from NYC Open Data & OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = Manhattan-grid east, z = grid south (north = -z), origin at the centreline
// intersection of 5th Ave & 42nd St; the axes are turned 29° from true north like the street grid itself.
// Every street and avenue sits where it really is: 59th St at z = -1370, 110th St at z = -5508, 14th St at z = 2219,
// 8th Ave at x = -860, 1st Ave at x = 1067. The detailed island runs from ~129th St (z = GEO.frame.cutZ) down to the
// Battery (z ≈ 6560); Harlem's northern half, Washington Heights & Inwood beyond are low-detail (boroughs.js).

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};
const CUT_Z = GEO.frame.cutZ;
function ordinal(n) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

// ---------------------------------------------------------------------------------------------------------------------
// Numbered streets: real z of every street (1st..~130th St) & its x-runs ([x0, x1, dir (+1 east / -1 west / 0 both),
// curb-to-curb roadway width])
// ---------------------------------------------------------------------------------------------------------------------
const STREET_BY_NUMBER = new Map(GEO.streets.map((s) => [s.n, s]));
function streetZ(n) {
  const s = STREET_BY_NUMBER.get(n);
  if (s) return s.z;
  // interpolate a missing number from its neighbours (~79.5 m per street)
  let lo = n - 1;
  let hi = n + 1;
  while (lo > 0 && !STREET_BY_NUMBER.has(lo)) lo--;
  while (hi < 300 && !STREET_BY_NUMBER.has(hi)) hi++;
  const a = STREET_BY_NUMBER.get(lo);
  const b = STREET_BY_NUMBER.get(hi);
  if (a && b) return a.z + ((n - lo) / (hi - lo)) * (b.z - a.z);
  return (42 - n) * 79.5;
}

