// Outer suspension bridges (skyline landmarks) from their towers' real positions: George Washington Bridge at 178th St
// (main span 1067 m, towers 184 m, side spans 186 m & 198 m), Verrazzano-Narrows Bridge from Fort Wadsworth to Fort
// Hamilton (main span 1298 m, towers 211 m, side spans 370 m). `a` / `b` = the deck model's ends, past the anchorages.
function outerBridge(id, name, short, type, tA, tB, backA, backB, extra) {
  const dx = tB[0] - tA[0];
  const dz = tB[1] - tA[1];
  const span = Math.hypot(dx, dz);
  const ux = dx / span;
  const uz = dz / span;
  const L = backA + span + backB;
  return {
    id, name, short, type,
    a: { x: tA[0] - ux * backA, z: tA[1] - uz * backA },
    b: { x: tB[0] + ux * backB, z: tB[1] + uz * backB },
    towers: [backA / L, (backA + span) / L],
    ...extra
  };
}
